def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([3, 1, 4, 2]), fmt([-5, 2, -4, 3, 1, -1]), fmt([0, 0, 0, 0]), fmt([1, 1, 1, 1]), fmt([-1, -1, -1, -1]),
             fmt([5, -3, 5, -3, 5]), fmt([-7, 4, 6, 5, -8, -9, 2]), fmt([10**5, -10**5, 10**5, -10**5]),
             fmt([-10**5, 10**5, -10**5, 10**5]), fmt([-2, 3, 5, -7, 0, 0])]
    for n in (4, 5, 6, 7, 8, 9, 10, 14):
        for _ in range(4):
            tests.append(fmt([rng.randint(-10, 10) for _ in range(n)]))
    for _ in range(4):
        tests.append(fmt([rng.randint(0, 10) for _ in range(rng.randint(4, 12))]))
        tests.append(fmt([rng.randint(-10, 0) for _ in range(rng.randint(4, 12))]))
    tests.append(fmt([rng.randint(-10**5, 10**5) for _ in range(2000)]))
    tests.append(fmt([rng.randint(-10**5, 10**5) for _ in range(100000)]))
    tests.append(fmt([rng.randint(1, 10**5) for _ in range(100000)]))
    tests.append(fmt([-rng.randint(1, 10**5) for _ in range(99999)]))
    tests.append(fmt([(-1) ** i * 10**5 for i in range(100000)]))
    return tests
